<?php
require_once __DIR__ . '/includes/sessao.php';
require_once __DIR__ . '/config/conexao.php';
verificar_sessao();

$titulo_pagina = 'Painel';
$tipo_usuario = $_SESSION['usuario_tipo'];
$total_clientes = (int) $conn->query('SELECT COUNT(*) FROM clientes')->fetchColumn();
$total_funcionarios = (int) $conn->query('SELECT COUNT(*) FROM usuarios WHERE ativo = 1')->fetchColumn();
$filtro_os = $tipo_usuario === 'mecanico' ? ' JOIN os_responsaveis r ON r.os_id = os.id AND r.usuario_id = ' . (int) $_SESSION['usuario_id'] . ' AND r.concluido_em IS NULL ' : '';
$os_abertas = (int) $conn->query("SELECT COUNT(*) FROM ordens_servico os $filtro_os WHERE os.status NOT IN ('entregue', 'cancelada')")->fetchColumn();
$pecas_pendentes = $tipo_usuario === 'mecanico'
    ? (int) $conn->query("SELECT COUNT(*) FROM pedidos_pecas p JOIN os_responsaveis r ON r.os_id = p.os_id AND r.usuario_id = " . (int) $_SESSION['usuario_id'] . " AND r.concluido_em IS NULL WHERE p.status IN ('solicitado','validado','pedido','a_caminho')")->fetchColumn()
    : (int) $conn->query("SELECT COUNT(*) FROM pedidos_pecas WHERE status IN ('solicitado','validado','pedido','a_caminho')")->fetchColumn();
$stmt = $conn->query("SELECT os.id, os.numero, os.status, os.prioridade, c.nome AS cliente, v.modelo, v.placa FROM ordens_servico os $filtro_os JOIN clientes c ON c.id = os.cliente_id LEFT JOIN veiculos v ON v.id = os.veiculo_id WHERE os.status NOT IN ('entregue', 'cancelada') ORDER BY FIELD(os.prioridade, 'urgente', 'alta', 'normal', 'baixa'), os.data_entrada LIMIT 10");
$ordens = $stmt->fetchAll();
$status_nomes = ['recebida' => 'Recebida', 'triagem' => 'Triagem', 'aguardando_diagnostico' => 'Aguardando diagnóstico', 'aguardando_orcamento' => 'Aguardando orçamento', 'aguardando_aprovacao' => 'Aguardando aprovação', 'aguardando_peca' => 'Aguardando peça', 'pronta_para_execucao' => 'Pronta para execução', 'em_execucao' => 'Em execução', 'aguardando_retorno' => 'Aguardando retorno', 'pronta_para_entrega' => 'Pronta para entrega'];
require_once __DIR__ . '/includes/header.php';
require_once __DIR__ . '/includes/mensagens.php';
?>
<div class="page-header"><div><h1><i data-lucide="layout-dashboard"></i>Painel</h1><span class="page-subtitle">Acompanhe o trabalho da oficina</span></div><?php if (tem_papel(['admin', 'secretaria', 'mecanico_chefe'])): ?><a href="pages/ordens_servico/cadastrar.php" class="btn btn-primary btn-icon action-button"><i data-lucide="clipboard-plus"></i>Novo atendimento</a><?php endif; ?></div>
<div class="row g-3 mb-4"><div class="col-6 col-xl-3"><div class="stat-card border-accent"><div class="stat-header"><span class="stat-label">Clientes</span><span class="stat-icon"><i data-lucide="users"></i></span></div><div class="stat-value"><?php echo $total_clientes; ?></div><div class="stat-delta">cadastrados</div></div></div><div class="col-6 col-xl-3"><div class="stat-card border-blue"><div class="stat-header"><span class="stat-label">Funcionários</span><span class="stat-icon blue"><i data-lucide="users-round"></i></span></div><div class="stat-value"><?php echo $total_funcionarios; ?></div><div class="stat-delta">ativos</div></div></div><div class="col-6 col-xl-3"><div class="stat-card border-yellow"><div class="stat-header"><span class="stat-label">OS em andamento</span><span class="stat-icon yellow"><i data-lucide="clipboard-list"></i></span></div><div class="stat-value"><?php echo $os_abertas; ?></div><div class="stat-delta"><?php echo $tipo_usuario === 'mecanico' ? 'atribuídas a você' : 'não encerradas'; ?></div></div></div><div class="col-6 col-xl-3"><div class="stat-card border-red"><div class="stat-header"><span class="stat-label">Peças pendentes</span><span class="stat-icon red"><i data-lucide="package-search"></i></span></div><div class="stat-value"><?php echo $pecas_pendentes; ?></div><div class="stat-delta"><?php echo $tipo_usuario === 'mecanico' ? 'das suas OS' : 'aguardando validação ou chegada'; ?></div></div></div></div>
<div class="row g-3"><div class="col-lg-9"><div class="card"><div class="card-header"><i data-lucide="clipboard-list" class="me-2"></i>Ordens de serviço <a href="pages/ordens_servico/listar.php" class="btn btn-sm btn-link float-end">Ver todas</a></div><div class="card-body p-0"><div class="table-responsive"><table class="table table-hover align-middle mb-0 responsive-card"><thead><tr><th>OS</th><th>Cliente</th><th>Veículo</th><th>Status</th><th>Prioridade</th></tr></thead><tbody><?php foreach ($ordens as $ordem): ?><tr><td data-label="OS"><a href="pages/ordens_servico/detalhes.php?id=<?php echo (int) $ordem['id']; ?>">#<?php echo str_pad((int) $ordem['numero'], 4, '0', STR_PAD_LEFT); ?></a></td><td data-label="Cliente"><?php echo esc($ordem['cliente']); ?></td><td data-label="Veículo"><?php echo esc($ordem['placa'] ?: $ordem['modelo'] ?: '-'); ?></td><td data-label="Status"><span class="badge badge-status-<?php echo esc($ordem['status']); ?>"><?php echo esc($status_nomes[$ordem['status']] ?? $ordem['status']); ?></span></td><td data-label="Prioridade"><span class="badge badge-prioridade-<?php echo esc($ordem['prioridade']); ?>"><?php echo esc(ucfirst($ordem['prioridade'])); ?></span></td></tr><?php endforeach; ?><?php if (!$ordens): ?><tr class="row-empty"><td colspan="5"><div class="empty-state"><div class="empty-state-icon"><i data-lucide="clipboard-check"></i></div><h4>Nenhuma OS em andamento</h4><p>Tudo em ordem! Nenhuma ordem de serviço aberta no momento.</p></div></td></tr><?php endif; ?></tbody></table></div></div></div></div><div class="col-lg-3"><div class="card"><div class="card-header"><i data-lucide="zap" class="me-2"></i>Ações rápidas</div><div class="card-body"><div class="quick-actions"><?php if (tem_papel(['admin', 'secretaria', 'mecanico_chefe'])): ?><a href="pages/ordens_servico/cadastrar.php" class="quick-action-btn"><i data-lucide="clipboard-plus"></i><span>Novo atendimento</span></a><?php endif; ?><?php if (tem_papel(['admin', 'secretaria', 'mecanico_chefe'])): ?><a href="pages/clientes/cadastrar.php" class="quick-action-btn"><i data-lucide="user-plus"></i><span>Novo cliente</span></a><?php endif; ?><?php if (tem_papel(['admin', 'secretaria', 'mecanico_chefe'])): ?><a href="pages/funcionarios/listar.php" class="quick-action-btn"><i data-lucide="users-round"></i><span>Funcionários</span></a><?php endif; ?><a href="pages/pedidos_pecas/listar.php" class="quick-action-btn"><i data-lucide="truck"></i><span>Pedidos de peças</span></a></div></div></div></div></div>
